using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Coordinates;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Positional;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Positional;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Validation.OrbitalAndPositional;
public sealed class AstronomyAngularPositionValidationRuleTests { [Fact] public void Valid_equatorial_and_horizontal_positions_pass() { Assert.Empty(new AstronomyAngularPositionValidationRule().Validate(OrbitalPositionalValidationFixture.AngularPayload(), OrbitalPositionalValidationFixture.Context())); Assert.Empty(new AstronomyAngularPositionValidationRule().Validate(OrbitalPositionalValidationFixture.AngularPayload(AstronomyCoordinateSystem.Horizontal, AstronomyAngularCoordinateComponent.Azimuth, AstronomyAngularCoordinateComponent.Altitude), OrbitalPositionalValidationFixture.Context())); } [Fact] public void Right_ascension_plus_latitude_is_rejected() { var payload = OrbitalPositionalValidationFixture.AngularPayload(AstronomyCoordinateSystem.Equatorial, AstronomyAngularCoordinateComponent.RightAscension, AstronomyAngularCoordinateComponent.Latitude); Assert.Contains(new AstronomyAngularPositionValidationRule().Validate(payload, OrbitalPositionalValidationFixture.Context()), i => i.Code == AstronomyPositionalValidationCodes.CoordinateSystemMismatch); } [Fact] public void Equatorial_pair_is_rejected_for_horizontal() { var payload = OrbitalPositionalValidationFixture.AngularPayload(AstronomyCoordinateSystem.Horizontal); Assert.Contains(new AstronomyAngularPositionValidationRule().Validate(payload, OrbitalPositionalValidationFixture.Context()), i => i.Code == AstronomyPositionalValidationCodes.CoordinateSystemMismatch); } [Fact] public void Duplicate_components_are_constructor_protected() => Assert.Throws<ArgumentException>(() => new AstronomyAngularPositionValue(OrbitalPositionalValidationFixture.Angular(AstronomyAngularCoordinateComponent.RightAscension), OrbitalPositionalValidationFixture.Angular(AstronomyAngularCoordinateComponent.RightAscension))); }
